'use strict';
/* Module 12 · Track B · BUMN joint recruitment (12.7 to 12.10) */
const { b, sec, flow, cmp, scen, step, mist, gl, chk, tool, take, res, rf, lesson, dur, NOTICE } = require('./h');
const VERIFY = { en: 'Stages, item counts, timing, wrong-answer penalties and the English provider differ between joint-recruitment cycles. The Lab’s config shows its source and verified date; always check the current FHCI announcement.', id: 'Tahapan, jumlah soal, waktu, penalti jawaban salah, dan penyedia tes bahasa Inggris berbeda antar siklus rekrutmen bersama. Konfigurasi Lab menampilkan sumber dan tanggal verifikasinya; selalu cek pengumuman FHCI yang berlaku.' };

const L127 = lesson({
  n: '12.7', kind: 'reading', dur: dur(40),
  title: b('BUMN Joint Recruitment: Stages and the TKD', 'Rekrutmen Bersama BUMN: Tahapan dan TKD'),
  overview: b('The joint recruitment of state-owned enterprises runs once or twice a year through a single portal and a shared first-round test. This lesson lays out the stages as they have typically run (registration and administrative screening, an online first round with a basic competency test and the AKHLAK values test, an English and learning-agility round, then each enterprise’s own tests and interviews), what the basic competency test (TKD) contains, how it maps onto the families you have trained, and the pacing for a 40-item timed set. Every stage detail is marked for verification against the current announcement.', 'Rekrutmen bersama BUMN berjalan sekali atau dua kali setahun melalui satu portal dan satu tes putaran pertama bersama. Pelajaran ini memaparkan tahapan sebagaimana yang biasanya berjalan (registrasi dan seleksi administrasi, putaran pertama daring dengan tes kemampuan dasar dan tes nilai AKHLAK, putaran bahasa Inggris dan learning agility, lalu tes dan wawancara masing-masing BUMN), apa isi tes kemampuan dasar (TKD), bagaimana ia memetakan ke keluarga yang telah kamu latih, dan tempo untuk set berbatas waktu 40 soal. Setiap rincian tahapan ditandai untuk diverifikasi terhadap pengumuman yang berlaku.'),
  objectives: [b('Describe the joint-recruitment stages and where each test sits.', 'Menggambarkan tahapan rekrutmen bersama dan posisi tiap tes.'), b('Map the TKD onto the verbal, numerical, reasoning and figural families.', 'Memetakan TKD ke keluarga verbal, numerik, penalaran, dan figural.'), b('Read a joint-recruitment announcement for counts, time and penalties.', 'Membaca pengumuman rekrutmen bersama untuk jumlah, waktu, dan penalti.'), b('Pace a 40-item, 30-minute timed set.', 'Mengatur tempo set berbatas waktu 40 soal, 30 menit.')],
  readFirst: rf('Track B in four lines', 'Jalur B dalam empat baris', 'Stages, TKD, AKHLAK, English.', 'Tahapan, TKD, AKHLAK, bahasa Inggris.', [
    ['One portal, several stages', 'Satu portal, beberapa tahap', [['Registration, administrative screening, online first round, English and agility, the enterprise’s own stages.', 'Registrasi, seleksi administrasi, putaran pertama daring, bahasa Inggris dan agility, tahapan BUMN sendiri.'], ['Verify every stage against the current announcement.', 'Verifikasi setiap tahap terhadap pengumuman yang berlaku.']]],
    ['TKD is the families you know', 'TKD adalah keluarga yang kamu kenal', [['Verbal, numerical, reasoning, figural, under a short clock.', 'Verbal, numerik, penalaran, figural, di bawah jam yang pendek.'], ['The format layer is pacing and a possible penalty rule.', 'Lapisan formatnya adalah tempo dan kemungkinan aturan penalti.']]],
    ['AKHLAK is new', 'AKHLAK itu baru', [['A values test with ranked options; Lesson 12.8.', 'Tes nilai dengan opsi berjenjang; Pelajaran 12.8.'], ['No official key exists; the Lab publishes its reasoning.', 'Tidak ada kunci resmi; Lab menerbitkan penalarannya.']]],
    ['English and agility', 'Bahasa Inggris dan agility', [['A separate online round; Lesson 12.9.', 'Putaran daring terpisah; Pelajaran 12.9.'], ['Provider and bands vary by cycle.', 'Penyedia dan pita nilai berbeda per siklus.']]]
  ]),
  sections: [
    sec('map', 'The stages, as they have typically run', 'Tahapan, sebagaimana biasanya berjalan', 'The Forum Human Capital Indonesia (FHCI) coordinates the joint recruitment for participating enterprises. In recent cycles the sequence has been: <b>registration</b> on the portal with document upload and a choice of enterprise and position; <b>administrative screening</b> (degree, GPA, age, documents); an <b>online first round</b> with a basic competency test (TKD) and the AKHLAK values test, sometimes with a national-insight component; a <b>second online round</b> with English and a learning-agility instrument; then the <b>enterprise’s own stages</b> (field tests, interviews, medical) and the announcement. Dates, the exact composition of each round, pass rates and whether a stage is eliminatory change between cycles; read the current announcement line by line and write the facts into the Lab’s plan tracker.', 'Forum Human Capital Indonesia (FHCI) mengoordinasikan rekrutmen bersama untuk BUMN peserta. Pada siklus-siklus terakhir urutannya: <b>registrasi</b> di portal dengan unggah dokumen dan pilihan BUMN serta posisi; <b>seleksi administrasi</b> (ijazah, IPK, usia, dokumen); <b>putaran pertama daring</b> dengan tes kemampuan dasar (TKD) dan tes nilai AKHLAK, kadang dengan komponen wawasan kebangsaan; <b>putaran kedua daring</b> dengan bahasa Inggris dan instrumen learning agility; lalu <b>tahapan BUMN sendiri</b> (tes lapangan, wawancara, medis) dan pengumuman. Tanggal, komposisi persis tiap putaran, tingkat kelulusan, dan apakah suatu tahap bersifat gugur berubah antar siklus; baca pengumuman yang berlaku baris demi baris dan tulis faktanya ke pelacak rencana Lab.'),
    sec('layers', 'What the TKD contains', 'Isi TKD', 'The basic competency test is a general-ability battery: <b>verbal</b> (synonyms, antonyms, analogies, short passages), <b>numerical</b> (arithmetic, series, comparison, story problems), <b>reasoning</b> (syllogisms, analytic sets) and <b>figural</b> (series, analogies, odd-one-out, matrices). Nothing in it is new after Module 7 and Track A; the differences are the clock (short), the device (your own, at home, under proctoring rules) and the scoring rule, which in some cycles has included a penalty for wrong answers and in others has not. The Lab’s TKD presets use Metanoia’s practice format (60 items, 45 minutes, four families) and a timed set of 40 in 30 minutes; verify the real counts from the announcement.', 'Tes kemampuan dasar adalah baterai kemampuan umum: <b>verbal</b> (sinonim, antonim, analogi, wacana pendek), <b>numerik</b> (aritmetika, deret, perbandingan, soal cerita), <b>penalaran</b> (silogisme, set analitis), dan <b>figural</b> (deret, analogi, beda gambar, matriks). Tidak ada yang baru setelah Modul 7 dan Jalur A; perbedaannya adalah jam (pendek), perangkat (milikmu sendiri, di rumah, di bawah aturan pengawasan), dan aturan penilaian, yang pada sebagian siklus memuat penalti jawaban salah dan pada siklus lain tidak. Preset TKD Lab memakai format latihan Metanoia (60 soal, 45 menit, empat keluarga) dan set berbatas waktu 40 soal dalam 30 menit; verifikasi jumlah sebenarnya dari pengumuman.'),
    sec('search', 'Reading the announcement', 'Membaca pengumuman', 'Six facts to extract and write down: item count per section, time per section or total, the scoring rule (penalty or none), whether navigation back is allowed, the device and proctoring rules (camera on, single screen, browser lock), and the window in which you may sit the test. The penalty rule decides your guessing rule (Lesson 7.7): no penalty means answer everything; a penalty of a quarter point means guess only when you can eliminate two options. Write the six facts on the scrap-paper card you will use on the day.', 'Enam fakta untuk diambil dan ditulis: jumlah soal per bagian, waktu per bagian atau total, aturan penilaian (penalti atau tidak), apakah navigasi mundur diizinkan, aturan perangkat dan pengawasan (kamera menyala, satu layar, kunci peramban), dan jendela waktu kamu boleh mengerjakan tes. Aturan penalti menentukan aturan menebakmu (Pelajaran 7.7): tanpa penalti berarti jawab semuanya; penalti seperempat poin berarti tebak hanya jika kamu bisa mengeliminasi dua opsi. Tulis enam fakta itu di kartu kertas coret yang akan kamu pakai pada harinya.'),
    sec('clock', 'Pacing the 40-item set', 'Tempo set 40 soal', 'Forty items in thirty minutes is 45 seconds each: verbal 30, numerical 50, reasoning 60, figural 45. Put checkpoints on the clock after each family. The Lab’s timed set prompts a skip at 1.5× the family target and flags the item; at the end you return to flags in order of family strength, strongest first, because those are the fastest to resolve. Home-test conditions add one more rule: test your connection, camera and browser the day before, and sit the set in the Lab on the same device at the same hour.', 'Empat puluh soal dalam tiga puluh menit adalah 45 detik per soal: verbal 30, numerik 50, penalaran 60, figural 45. Pasang titik periksa pada jam setelah tiap keluarga. Set berbatas waktu Lab mengajak melewati pada 1,5× target keluarga dan menandai soalnya; di akhir kamu kembali ke tanda berurutan dari keluarga terkuat, karena itu yang paling cepat diselesaikan. Kondisi tes di rumah menambah satu aturan: uji koneksi, kamera, dan peramban sehari sebelumnya, dan kerjakan set di Lab pada perangkat yang sama pada jam yang sama.')
  ],
  diagram: flow('Exhibit 1: Joint-recruitment stages (verify per cycle)', 'Peraga 1: Tahapan rekrutmen bersama (verifikasi per siklus)', 'Where each Lab preset sits', 'Di mana tiap preset Lab berada', [
    ['doc', 'Registration and screening', 'Registrasi dan seleksi', 'Documents, enterprise and position choice.', 'Dokumen, pilihan BUMN dan posisi.'],
    ['checkSq', 'Online round 1', 'Putaran daring 1', 'TKD and AKHLAK; Lab presets 12.7 and 12.8.', 'TKD dan AKHLAK; preset Lab 12.7 dan 12.8.'],
    ['globe', 'Online round 2', 'Putaran daring 2', 'English and learning agility; 12.9.', 'Bahasa Inggris dan learning agility; 12.9.'],
    ['users', 'Enterprise stages', 'Tahapan BUMN', 'Field tests, interviews, medical; The Rope.', 'Tes lapangan, wawancara, medis; The Rope.']
  ]),
  compare: [cmp('Two readings of the penalty line', 'Dua pembacaan baris penalti', 'The announcement says nothing about a penalty for wrong answers.', 'Pengumuman tidak menyebut apa pun tentang penalti jawaban salah.', 'Assumes there is one “to be safe” and leaves nine items blank. Nine certain zeros.', 'Mengandaikan ada penalti “biar aman” dan membiarkan sembilan soal kosong. Sembilan nol pasti.', 'Writes “no penalty stated” on the card, answers everything, flags nine, returns to them in family-strength order and resolves five. Expected gain: about two items.', 'Menulis “penalti tidak disebut” di kartu, menjawab semuanya, menandai sembilan, kembali berurutan kekuatan keluarga dan menyelesaikan lima. Perkiraan tambahan: sekitar dua soal.', 'The guessing rule follows the scoring rule as written; an unstated penalty is not a penalty.', 'Aturan menebak mengikuti aturan penilaian sebagaimana tertulis; penalti yang tidak disebut bukan penalti.')],
  scenario: scen('map', 'In focus: the third stage nobody read', 'Sorotan: tahap ketiga yang tidak dibaca siapa pun', [['A cohort of applicants prepared the TKD for a month and were surprised by the AKHLAK test in the same session, then by the English round two weeks later. The announcement had listed all three. The Lab’s plan tracker asks for the stage list on day one, and the Track B presets are ordered to match it: TKD timed set, AKHLAK drill and mirror, English set, then the combined BUMN-T1 mock.', 'Sekelompok pelamar menyiapkan TKD selama sebulan dan terkejut oleh tes AKHLAK dalam sesi yang sama, lalu oleh putaran bahasa Inggris dua minggu kemudian. Pengumuman telah mencantumkan ketiganya. Pelacak rencana Lab meminta daftar tahapan pada hari pertama, dan preset Jalur B diurutkan agar sesuai: set TKD berbatas waktu, latihan AKHLAK dan cermin, set bahasa Inggris, lalu simulasi gabungan BUMN-T1.']]),
  steps: [
    step('Step 1 · Extract the six facts', 'Langkah 1 · Ambil enam fakta', 'From the current announcement (or the last one, if the next is not out), write item counts, time, penalty rule, navigation, device rules and the sitting window into the plan tracker.', 'Dari pengumuman yang berlaku (atau yang terakhir, jika yang berikut belum terbit), tulis jumlah soal, waktu, aturan penalti, navigasi, aturan perangkat, dan jendela pengerjaan ke pelacak rencana.', 'Facts you could not find are questions for the portal’s help desk, not assumptions.', 'Fakta yang tidak kamu temukan adalah pertanyaan untuk pusat bantuan portal, bukan andaian.'),
    step('Step 2 · The 40-item timed set', 'Langkah 2 · Set berbatas waktu 40 soal', 'Sit the Lab’s TKD timed set (40 items, 30 minutes, four families) on the device you will use, with the checkpoints written down.', 'Kerjakan set TKD berbatas waktu Lab (40 soal, 30 menit, empat keluarga) pada perangkat yang akan kamu pakai, dengan titik periksa tertulis.', 'Read completion before accuracy: a TKD is lost more often on pace than on knowledge.', 'Baca penyelesaian sebelum ketepatan: TKD lebih sering hilang karena tempo daripada pengetahuan.'),
    step('Step 3 · Flags in strength order', 'Langkah 3 · Tanda berurutan kekuatan', 'In the review, note which flagged items you resolved and in which family. Next set: return to flags in your strongest family first.', 'Dalam tinjauan, catat soal bertanda mana yang kamu selesaikan dan di keluarga mana. Set berikutnya: kembali ke tanda di keluarga terkuatmu dulu.', 'Flags in a weak family cost time and rarely resolve; strongest-first is the rule.', 'Tanda di keluarga lemah memakan waktu dan jarang selesai; terkuat-dulu adalah aturannya.')
  ],
  mistakes: mist([['Preparing only the TKD', 'Menyiapkan TKD saja', 'AKHLAK and English are stages too; plan all three.', 'AKHLAK dan bahasa Inggris juga tahapan; rencanakan ketiganya.'], ['Assuming a penalty', 'Mengandaikan penalti', 'Read the scoring rule; the guessing rule follows it.', 'Baca aturan penilaian; aturan menebak mengikutinya.'], ['Sitting the test on an untested device', 'Mengerjakan tes di perangkat yang belum diuji', 'Connection, camera, browser, the day before.', 'Koneksi, kamera, peramban, sehari sebelumnya.'], ['Returning to flags in order', 'Kembali ke tanda berurutan nomor', 'Strongest family first.', 'Keluarga terkuat dulu.']]),
  glossary: gl([['FHCI', 'FHCI', 'Forum Human Capital Indonesia, coordinator of the joint recruitment.', 'Forum Human Capital Indonesia, koordinator rekrutmen bersama.'], ['TKD', 'TKD', 'Tes Kemampuan Dasar: the general-ability battery of the first online round.', 'Tes Kemampuan Dasar: baterai kemampuan umum putaran daring pertama.'], ['AKHLAK', 'AKHLAK', 'The six BUMN core values, tested with ranked scenario options.', 'Enam nilai inti BUMN, diuji dengan opsi skenario berjenjang.'], ['Learning agility', 'Learning agility', 'An instrument on how you learn from experience; provider varies.', 'Instrumen tentang cara kamu belajar dari pengalaman; penyedia berbeda-beda.'], ['Eliminatory stage', 'Tahap gugur', 'A stage whose result removes candidates from the next.', 'Tahap yang hasilnya menggugurkan kandidat dari tahap berikutnya.'], ['Sitting window', 'Jendela pengerjaan', 'The dates and hours in which the online test may be taken.', 'Tanggal dan jam saat tes daring boleh dikerjakan.']]),
  checks: [
    chk('The TKD is best described as …', 'TKD paling tepat digambarkan sebagai …', [['a test of BUMN knowledge', 'tes pengetahuan BUMN'], ['a general-ability battery of the families trained in Module 7 and Track A', 'baterai kemampuan umum dari keluarga yang dilatih di Modul 7 dan Jalur A'], ['an English test', 'tes bahasa Inggris'], ['a personality questionnaire', 'kuesioner kepribadian']], 1, 'Verbal, numerical, reasoning, figural; the format layer is new, the families are not.', 'Verbal, numerik, penalaran, figural; lapisan formatnya baru, keluarganya tidak.'),
    chk('The guessing rule for the TKD comes from …', 'Aturan menebak untuk TKD berasal dari …', [['habit', 'kebiasaan'], ['the scoring rule in the current announcement', 'aturan penilaian di pengumuman yang berlaku'], ['last year’s forum posts', 'unggahan forum tahun lalu'], ['the number of options', 'jumlah opsi']], 1, 'No penalty stated means answer everything; a penalty changes the threshold for guessing.', 'Penalti yang tidak disebut berarti jawab semuanya; penalti mengubah ambang untuk menebak.'),
    chk('Which Lab preset matches the first online round?', 'Preset Lab mana yang cocok dengan putaran daring pertama?', [['the Kraepelin simulator', 'simulator Kraepelin'], ['the TKD timed set and the AKHLAK drill', 'set TKD berbatas waktu dan latihan AKHLAK'], ['the SKD-110 simulation', 'simulasi SKD-110'], ['the English set only', 'set bahasa Inggris saja']], 1, 'Round 1 has typically combined the TKD and the AKHLAK test; verify per cycle.', 'Putaran 1 biasanya menggabungkan TKD dan tes AKHLAK; verifikasi per siklus.')
  ],
  tool: tool('timed:tkd40', 'The TKD timed set', 'Set TKD berbatas waktu', 'Forty original items, 30 minutes, four families with per-family targets, skip prompts and flags; report by family with completion, accuracy and median time. A Metanoia practice form in a TKD-like format; not an imitation of any institution’s interface.', 'Empat puluh soal asli, 30 menit, empat keluarga dengan target per keluarga, ajakan melewati, dan tanda; laporan per keluarga dengan penyelesaian, ketepatan, dan waktu median. Formulir latihan Metanoia dalam format mirip TKD; bukan tiruan antarmuka lembaga mana pun.', 'Start the timed set →', 'Mulai set berbatas waktu →'),
  takeaways: take([['Read the announcement into six facts before you practise.', 'Baca pengumuman menjadi enam fakta sebelum berlatih.'], ['The TKD is the families you know, under a short clock, on your own device.', 'TKD adalah keluarga yang kamu kenal, di bawah jam pendek, di perangkatmu sendiri.'], ['Checkpoints per family, flags resolved strongest family first.', 'Titik periksa per keluarga, tanda diselesaikan dari keluarga terkuat.']]),
  resources: res('Verification', 'Verifikasi', 'What changes between cycles.', 'Apa yang berubah antar siklus.', [['Read the current announcement', 'Baca pengumuman yang berlaku', 'Then the portal help desk.', 'Lalu pusat bantuan portal.', [[VERIFY.en, VERIFY.id], [NOTICE.en, NOTICE.id]]]])
});

const L128 = lesson({
  n: '12.8', kind: 'interactive', dur: dur(50),
  title: b('AKHLAK: Six Values, Ranked Scoring, Consistency', 'AKHLAK: Enam Nilai, Skor Berjenjang, Konsistensi'),
  overview: b('The AKHLAK test asks what you would do in workplace scenarios and scores every option, not just one. This lesson sets out the six values with their behaviour guides, explains ranked scoring and why “second best” is the habit that costs most, gives the ladder that the Lab’s keys follow and the three traps that pull candidates down it, and introduces the consistency mirror. The Lab’s keys are Metanoia’s reasoning, published with the ladder; FHCI publishes no key.', 'Tes AKHLAK menanyakan apa yang akan kamu lakukan dalam skenario kerja dan menilai setiap opsi, bukan hanya satu. Pelajaran ini memaparkan enam nilai dengan panduan perilakunya, menjelaskan skor berjenjang dan mengapa “terbaik kedua” adalah kebiasaan yang paling mahal, memberi tangga yang diikuti kunci Lab dan tiga jebakan yang menarik kandidat turun darinya, dan memperkenalkan cermin konsistensi. Kunci Lab adalah penalaran Metanoia, diterbitkan beserta tangganya; FHCI tidak menerbitkan kunci.'),
  objectives: [b('State the six AKHLAK values and one behaviour guide for each.', 'Menyebutkan enam nilai AKHLAK dan satu panduan perilaku untuk masing-masing.'), b('Explain ranked scoring and compute a scenario score.', 'Menjelaskan skor berjenjang dan menghitung skor sebuah skenario.'), b('Apply the ladder (proactive, within authority, root cause, people and rules) to rank options.', 'Menerapkan tangga (proaktif, dalam kewenangan, akar masalah, orang dan aturan) untuk mengurutkan opsi.'), b('Use the consistency mirror to find and resolve contradictions in your own answers.', 'Memakai cermin konsistensi untuk menemukan dan menyelesaikan pertentangan dalam jawabanmu sendiri.')],
  readFirst: rf('Six values, one ladder', 'Enam nilai, satu tangga', 'What AKHLAK scores and how to climb.', 'Apa yang dinilai AKHLAK dan cara menaikinya.', [
    ['Six values', 'Enam nilai', [['Amanah, Kompeten, Harmonis, Loyal, Adaptif, Kolaboratif.', 'Amanah, Kompeten, Harmonis, Loyal, Adaptif, Kolaboratif.'], ['Each has a behaviour guide; the test scenarios are built on them.', 'Masing-masing punya panduan perilaku; skenario tes dibangun di atasnya.']]],
    ['Every option scores', 'Setiap opsi bernilai', [['Ranked scoring: 5 for the best, 1 for the worst, nothing for blank.', 'Skor berjenjang: 5 untuk terbaik, 1 untuk terburuk, nol untuk kosong.'], ['Choosing 4s all day is the expensive habit.', 'Memilih 4 sepanjang hari adalah kebiasaan yang mahal.']]],
    ['The ladder', 'Tangga', [['5: proactive, within authority, fixes the cause, keeps people and rules.', '5: proaktif, dalam kewenangan, membereskan sebab, menjaga orang dan aturan.'], ['1: harms, breaks a rule, or is loyal to a person over the institution.', '1: merugikan, melanggar aturan, atau setia pada orang di atas institusi.']]]
  ]),
  sections: [
    sec('heart', 'The six values and their behaviour guides', 'Enam nilai dan panduan perilakunya', '<b>Amanah</b>: keep your word, be honest, take responsibility, respect the rules and the assets entrusted to you. <b>Kompeten</b>: keep learning, help others learn, deliver the best quality. <b>Harmonis</b>: care for people, respect differences, build a conducive environment. <b>Loyal</b>: dedication to the institution and the nation, protect its name and its secrets, loyal to values before persons. <b>Adaptif</b>: welcome change, innovate, act before being told. <b>Kolaboratif</b>: give others room to contribute, be open to working together, mobilise shared resources. The scenarios in a values test are built from these guides: each describes a situation where one value is under pressure and asks how you would act. Naming the value under pressure is the first move on every item.', '<b>Amanah</b>: memegang janji, jujur, bertanggung jawab, menghormati aturan dan aset yang dipercayakan. <b>Kompeten</b>: terus belajar, membantu orang lain belajar, memberikan kualitas terbaik. <b>Harmonis</b>: peduli pada orang, menghargai perbedaan, membangun lingkungan yang kondusif. <b>Loyal</b>: berdedikasi pada institusi dan bangsa, menjaga nama baik dan rahasianya, setia pada nilai sebelum orang. <b>Adaptif</b>: menyambut perubahan, berinovasi, bertindak sebelum disuruh. <b>Kolaboratif</b>: memberi ruang orang lain berkontribusi, terbuka bekerja sama, menggerakkan sumber daya bersama. Skenario dalam tes nilai dibangun dari panduan ini: masing-masing menggambarkan situasi ketika satu nilai berada di bawah tekanan dan menanyakan bagaimana kamu bertindak. Menamai nilai yang tertekan adalah langkah pertama pada setiap soal.'),
    sec('chart', 'Ranked scoring and the “second best” habit', 'Skor berjenjang dan kebiasaan “terbaik kedua”', 'In ranked scoring every option carries a value from 5 (best) to 1 (worst); a blank scores 0. Thirty scenarios make 150 points possible. The arithmetic has a consequence most candidates miss: picking the <b>second-best</b> option on every item scores 120, the same as picking the best on 24 and the worst on 6. Candidates who are “sensible” but cautious choose 4s all day: the answer that helps but does not fix, that informs but does not act, that is safe but passive. The Lab reports your <b>second-best share</b> (the proportion of your picks that scored 4) because reducing it is the single largest gain available on this test.', 'Dalam skor berjenjang setiap opsi membawa nilai dari 5 (terbaik) sampai 1 (terburuk); kosong bernilai 0. Tiga puluh skenario memungkinkan 150 poin. Aritmetikanya punya akibat yang dilewatkan kebanyakan kandidat: memilih opsi <b>terbaik kedua</b> pada setiap soal menghasilkan 120, sama dengan memilih terbaik pada 24 dan terburuk pada 6. Kandidat yang “masuk akal” tetapi berhati-hati memilih 4 sepanjang hari: jawaban yang membantu tetapi tidak membereskan, yang memberi tahu tetapi tidak bertindak, yang aman tetapi pasif. Lab melaporkan <b>porsi terbaik kedua</b>-mu (proporsi pilihanmu yang bernilai 4) karena menguranginya adalah satu-satunya perolehan terbesar yang tersedia pada tes ini.'),
    sec('trendUp', 'The ladder', 'Tangga', 'The Lab’s keys follow one ladder, stated on every review screen. <b>5</b>: proactive, within your authority, resolves the root cause, keeps the people and the rules intact (often two moves: act now, fix the system). <b>4</b>: good but partial or passive (acts on the symptom, informs without acting, helps one person without fixing the source). <b>3</b>: neutral or deferring (passes it to the boss, waits, follows the letter of the rule without serving its purpose). <b>2</b>: avoids (leaves the group, stays silent, lets it pass). <b>1</b>: harms or breaks a rule (covers up, gossips, retaliates, obeys a person over the institution). Rank from the ends: find the 1 and the 5 first; the middle is easier once the poles are fixed.', 'Kunci Lab mengikuti satu tangga, dinyatakan di setiap layar tinjauan. <b>5</b>: proaktif, dalam kewenanganmu, menyelesaikan akar masalah, menjaga orang dan aturan tetap utuh (sering dua langkah: bertindak sekarang, perbaiki sistem). <b>4</b>: baik tetapi sebagian atau pasif (menangani gejala, memberi tahu tanpa bertindak, membantu satu orang tanpa membereskan sumbernya). <b>3</b>: netral atau menyerahkan (melimpahkan ke atasan, menunggu, mengikuti bunyi aturan tanpa melayani tujuannya). <b>2</b>: menghindar (keluar dari kelompok, diam, membiarkan). <b>1</b>: merugikan atau melanggar aturan (menutupi, menggunjing, membalas, menaati orang di atas institusi). Urutkan dari ujung: temukan 1 dan 5 dulu; bagian tengah lebih mudah setelah kutubnya tetap.'),
    sec('x', 'Three traps', 'Tiga jebakan', 'The <b>heroic</b> option acts outside your authority (overrules the boss, releases the data, changes the procedure yourself) and reads as bold; it scores 2 or 1 because institutions run on authority. The <b>loyal-to-a-person</b> option keeps a secret for a manager or covers a colleague and reads as loyal; Loyal means loyal to the institution and its values, so it scores 1. The <b>second-best</b> option is the one you reach for when tired: it helps, informs, or waits, and never fixes. Each review screen names the trap each option represents; your trap tags accumulate in the error log.', 'Opsi <b>heroik</b> bertindak di luar kewenanganmu (membatalkan keputusan atasan, membuka data, mengubah prosedur sendiri) dan terbaca berani; nilainya 2 atau 1 karena institusi berjalan di atas kewenangan. Opsi <b>setia-pada-orang</b> menyimpan rahasia untuk manajer atau menutupi rekan dan terbaca loyal; Loyal berarti setia pada institusi dan nilainya, sehingga nilainya 1. Opsi <b>terbaik kedua</b> adalah yang kamu raih saat lelah: membantu, memberi tahu, atau menunggu, dan tidak pernah membereskan. Setiap layar tinjauan menamai jebakan yang diwakili tiap opsi; tanda jebakanmu terkumpul di catatan kesalahan.'),
    sec('refresh', 'The consistency mirror', 'Cermin konsistensi', 'Values tests often include consistency checks: the same disposition asked in two framings. The Lab’s mirror asks six pairs (one per value), a positive statement and its reversed form, on a five-point scale, then shows where your two answers disagree. Disagreement is not failure; it is information: it usually means you answered the surface wording rather than the disposition. Resolve each disagreement by deciding what you actually do at work, then answer both forms the same way. The mirror is for you; nothing from it leaves your device.', 'Tes nilai sering memuat pemeriksaan konsistensi: disposisi yang sama ditanyakan dalam dua bingkai. Cermin Lab menanyakan enam pasangan (satu per nilai), pernyataan positif dan bentuk terbaliknya, pada skala lima poin, lalu menunjukkan di mana kedua jawabanmu tidak sepakat. Ketidaksepakatan bukan kegagalan; itu informasi: biasanya berarti kamu menjawab kata-kata permukaan alih-alih disposisinya. Selesaikan tiap ketidaksepakatan dengan memutuskan apa yang benar-benar kamu lakukan di tempat kerja, lalu jawab kedua bentuk dengan cara yang sama. Cermin itu untukmu; tidak ada yang keluar dari perangkatmu.')
  ],
  diagram: flow('Exhibit 1: The ladder', 'Peraga 1: Tangga', 'How every AKHLAK and TKP key in the Lab is reasoned', 'Cara setiap kunci AKHLAK dan TKP di Lab dinalar', [
    ['star', '5 · Fixes it', '5 · Membereskan', 'Proactive, within authority, root cause, people and rules intact.', 'Proaktif, dalam kewenangan, akar masalah, orang dan aturan utuh.'],
    ['check', '4 · Helps', '4 · Membantu', 'Good but partial or passive.', 'Baik tetapi sebagian atau pasif.'],
    ['info', '3 · Defers', '3 · Menyerahkan', 'Neutral; passes it on; letter without purpose.', 'Netral; melimpahkan; bunyi tanpa tujuan.'],
    ['arrowL', '2 · Avoids', '2 · Menghindar', 'Leaves, stays silent, lets it pass.', 'Pergi, diam, membiarkan.'],
    ['x', '1 · Harms', '1 · Merugikan', 'Breaks a rule or is loyal to a person over the institution.', 'Melanggar aturan atau setia pada orang di atas institusi.']
  ]),
  compare: [cmp('Two answers to the same scenario', 'Dua jawaban untuk skenario yang sama', 'Your manager asks you to keep a safety violation he committed to yourself, “out of loyalty”.', 'Manajermu memintamu menyimpan pelanggaran keselamatan yang ia lakukan, “demi loyalitas”.', 'Keeps it this once, on condition it does not recur. Feels loyal. Scores 1: a cover-up, loyal to a person over the institution and the safety of others.', 'Menyimpannya kali ini, dengan syarat tidak terulang. Terasa loyal. Bernilai 1: menutupi, setia pada orang di atas institusi dan keselamatan orang lain.', 'Declines to cover it and reports through the company’s own channel, because Loyal is loyalty to the institution and to safety. Scores 5.', 'Menolak menutupi dan melapor lewat saluran perusahaan sendiri, karena Loyal adalah kesetiaan pada institusi dan keselamatan. Bernilai 5.', 'The word “loyalty” in the scenario is the trap; the value’s own guide defines the direction of loyalty.', 'Kata “loyalitas” dalam skenario adalah jebakannya; panduan nilainya sendiri menentukan arah kesetiaan.')],
  scenario: scen('chart', 'In focus: 118 out of 150', 'Sorotan: 118 dari 150', [['A candidate scored 118 on the Lab’s thirty-scenario set with only two 1s and no blanks. Her second-best share was 70%: twenty-one 4s. Every one of them was the “inform the boss” or “help this once” option. After one session with the ladder and the review screens, her next set was 136, with the same two 1s: the gain came entirely from 4s becoming 5s.', 'Seorang kandidat mendapat 118 pada set tiga puluh skenario Lab dengan hanya dua nilai 1 dan tanpa kosong. Porsi terbaik keduanya 70%: dua puluh satu nilai 4. Setiap satunya adalah opsi “beri tahu atasan” atau “bantu kali ini”. Setelah satu sesi dengan tangga dan layar tinjauan, set berikutnya 136, dengan dua nilai 1 yang sama: perolehannya seluruhnya dari 4 yang menjadi 5.']]),
  steps: [
    step('Drill 1 · Name the value, find the poles', 'Latihan 1 · Sebutkan nilainya, temukan kutubnya', 'Twelve AKHLAK scenarios in the Lab. For each, write the value under pressure, then mark the 1 and the 5 before ranking the middle.', 'Dua belas skenario AKHLAK di Lab. Untuk tiap skenario, tulis nilai yang tertekan, lalu tandai 1 dan 5 sebelum mengurutkan bagian tengah.', 'Compare your 5 with the key’s and read the ladder reason. Disagreements are allowed; note yours in the Dossier with the reason.', 'Bandingkan 5-mu dengan kunci dan baca alasan tangganya. Ketidaksepakatan diperbolehkan; catat milikmu di Dossier beserta alasannya.'),
    step('Drill 2 · Cut the second-best share', 'Latihan 2 · Pangkas porsi terbaik kedua', 'Twelve more scenarios. Before confirming any pick, ask “does this fix the cause, or only help?”. Aim for a second-best share under 30%.', 'Dua belas skenario lagi. Sebelum mengonfirmasi pilihan apa pun, tanyakan “apakah ini membereskan sebabnya, atau hanya membantu?”. Targetkan porsi terbaik kedua di bawah 30%.', 'The report shows the share; it falls faster than accuracy rises because 4s were never wrong, only incomplete.', 'Laporan menampilkan porsinya; ia turun lebih cepat daripada ketepatan naik karena 4 tidak pernah salah, hanya tidak lengkap.'),
    step('Drill 3 · The mirror', 'Latihan 3 · Cermin', 'Run the consistency mirror. For each disagreement, write what you actually do at work in one sentence, then answer both forms accordingly and run it again.', 'Jalankan cermin konsistensi. Untuk tiap ketidaksepakatan, tulis apa yang benar-benar kamu lakukan di tempat kerja dalam satu kalimat, lalu jawab kedua bentuk sesuai itu dan jalankan lagi.', 'Two runs with zero disagreements is the goal; the sentences are the Dossier item.', 'Dua kali jalan dengan nol ketidaksepakatan adalah tujuannya; kalimat-kalimatnya adalah butir Dossier.')
  ],
  mistakes: mist([['Choosing the safe 4', 'Memilih 4 yang aman', 'Ask whether the option fixes the cause; 5s act and repair.', 'Tanyakan apakah opsi membereskan sebab; 5 bertindak dan memperbaiki.'], ['Reading “loyalty” as loyalty to a person', 'Membaca “loyalitas” sebagai kesetiaan pada orang', 'Loyal is to the institution and its values.', 'Loyal adalah pada institusi dan nilainya.'], ['Being heroic outside your authority', 'Heroik di luar kewenangan', 'Authority is part of the ladder; act within it and escalate.', 'Kewenangan adalah bagian tangga; bertindak di dalamnya dan eskalasi.'], ['Answering the wording, not the disposition', 'Menjawab kata-katanya, bukan disposisinya', 'The mirror catches it; decide what you do, then answer both forms.', 'Cermin menangkapnya; putuskan apa yang kamu lakukan, lalu jawab kedua bentuk.']]),
  glossary: gl([['Ranked scoring', 'Skor berjenjang', 'Every option carries a value 1 to 5; blank is 0.', 'Setiap opsi bernilai 1 sampai 5; kosong 0.'], ['Second-best share', 'Porsi terbaik kedua', 'The proportion of your picks that scored 4.', 'Proporsi pilihanmu yang bernilai 4.'], ['Behaviour guide', 'Panduan perilaku', 'The published description of what each value looks like in action.', 'Deskripsi terbitan tentang wujud tiap nilai dalam tindakan.'], ['Reasoning key', 'Kunci penalaran', 'Metanoia’s ranking with its ladder reason; no official key exists.', 'Peringkat Metanoia beserta alasan tangganya; tidak ada kunci resmi.'], ['Consistency mirror', 'Cermin konsistensi', 'Paired statements in two framings that should agree.', 'Pernyataan berpasangan dalam dua bingkai yang seharusnya sepakat.'], ['Heroic option', 'Opsi heroik', 'Bold action outside your authority; scores low.', 'Tindakan berani di luar kewenangan; bernilai rendah.']]),
  checks: [
    chk('On a 30-scenario ranked test, choosing the second-best option every time scores …', 'Pada tes berjenjang 30 skenario, memilih opsi terbaik kedua setiap kali menghasilkan …', [['150', '150'], ['120', '120'], ['90', '90'], ['0', '0']], 1, '30 × 4 = 120; the same as 24 bests and 6 worsts.', '30 × 4 = 120; sama dengan 24 terbaik dan 6 terburuk.'),
    chk('“Loyal” in AKHLAK means loyalty to …', '“Loyal” dalam AKHLAK berarti kesetiaan pada …', [['your direct manager', 'manajer langsungmu'], ['the institution, the nation and the values, before any person', 'institusi, bangsa, dan nilai, sebelum orang mana pun'], ['your team', 'timmu'], ['your own career', 'kariermu sendiri']], 1, 'Covering for a person scores 1 under this value.', 'Menutupi seseorang bernilai 1 di bawah nilai ini.'),
    chk('Who publishes the key for the AKHLAK test?', 'Siapa yang menerbitkan kunci tes AKHLAK?', [['FHCI, each cycle', 'FHCI, tiap siklus'], ['nobody; the Lab’s keys are Metanoia’s reasoning, published with the ladder', 'tidak ada; kunci Lab adalah penalaran Metanoia, diterbitkan beserta tangganya'], ['the enterprise you applied to', 'BUMN yang kamu lamar'], ['the test provider, on request', 'penyedia tes, bila diminta']], 1, 'No official key exists; the reasoning is shown so you can disagree with it.', 'Tidak ada kunci resmi; penalarannya ditampilkan agar kamu bisa tidak sepakat dengannya.')
  ],
  tool: tool('drill:akhlak', 'AKHLAK drills and the mirror', 'Latihan AKHLAK dan cermin', 'Thirty-six original scenarios across the six values with ranked scoring, the ladder reason on every review, trap tags and the second-best share in the report; plus the six-pair consistency mirror. Keys are Metanoia’s reasoning; FHCI publishes no key.', 'Tiga puluh enam skenario asli dari enam nilai dengan skor berjenjang, alasan tangga pada setiap tinjauan, tanda jebakan, dan porsi terbaik kedua di laporan; plus cermin konsistensi enam pasangan. Kunci adalah penalaran Metanoia; FHCI tidak menerbitkan kunci.'),
  takeaways: take([['Name the value under pressure; find the 1 and the 5 first.', 'Sebutkan nilai yang tertekan; temukan 1 dan 5 lebih dulu.'], ['Cut the second-best share; 4s help, 5s fix.', 'Pangkas porsi terbaik kedua; 4 membantu, 5 membereskan.'], ['Loyal means the institution; heroic means outside authority; both are traps.', 'Loyal berarti institusi; heroik berarti di luar kewenangan; keduanya jebakan.']]),
  resources: res('The values, verbatim', 'Nilai-nilainya, apa adanya', 'Read the source, not a summary.', 'Baca sumbernya, bukan ringkasan.', [['Source', 'Sumber', 'Kementerian BUMN core values guide.', 'Panduan nilai inti Kementerian BUMN.', [['The AKHLAK core values and behaviour guide were set out by the Ministry of State-Owned Enterprises in 2020 (SE-7/MBU/07/2020). Read the six value statements and their behaviour guides in the original; the Lab’s scenarios are written against them but do not quote them.', 'Nilai inti AKHLAK dan panduan perilakunya ditetapkan Kementerian BUMN pada 2020 (SE-7/MBU/07/2020). Baca enam pernyataan nilai dan panduan perilakunya dalam teks aslinya; skenario Lab ditulis berdasarkan itu tetapi tidak mengutipnya.'], [NOTICE.en, NOTICE.id]]]])
});

const L129 = lesson({
  n: '12.9', kind: 'interactive', dur: dur(40),
  title: b('English and Learning Agility', 'Bahasa Inggris dan Learning Agility'),
  overview: b('The second online round has typically paired an English test with a learning-agility instrument. The English test is structure and reading at a business-English level; this lesson gives the three grammar families the test leans on, the three reading question types, and a 20-item set. The learning-agility instrument is a questionnaire about how you learn from experience; it cannot be gamed, and this lesson explains what it asks and how to answer it consistently and honestly.', 'Putaran daring kedua biasanya memasangkan tes bahasa Inggris dengan instrumen learning agility. Tes bahasa Inggrisnya adalah struktur dan membaca pada tingkat bahasa Inggris bisnis; pelajaran ini memberi tiga keluarga tata bahasa yang menjadi andalan tes, tiga jenis soal membaca, dan satu set 20 soal. Instrumen learning agility adalah kuesioner tentang cara kamu belajar dari pengalaman; tidak bisa diakali, dan pelajaran ini menjelaskan apa yang ditanyakan dan cara menjawabnya secara konsisten dan jujur.'),
  objectives: [b('Apply the three structure families: agreement, tense and aspect, clause form.', 'Menerapkan tiga keluarga struktur: kesesuaian, kala dan aspek, bentuk klausa.'), b('Answer main-idea, referent and inference questions from a short business passage.', 'Menjawab soal ide pokok, rujukan, dan inferensi dari wacana bisnis pendek.'), b('Describe what a learning-agility instrument measures.', 'Menggambarkan apa yang diukur instrumen learning agility.'), b('Answer disposition questionnaires consistently without pretending.', 'Menjawab kuesioner disposisi secara konsisten tanpa berpura-pura.')],
  readFirst: rf('Round two', 'Putaran dua', 'English you can train; agility you can only tell the truth about.', 'Bahasa Inggris bisa dilatih; agility hanya bisa dijawab dengan jujur.', [
    ['Three structure families', 'Tiga keluarga struktur', [['Agreement (head noun, not nearest noun), tense and aspect, clause form.', 'Kesesuaian (inti frasa, bukan kata terdekat), kala dan aspek, bentuk klausa.'], ['Strip the interrupting phrase before deciding.', 'Buang frasa penyela sebelum memutuskan.']]],
    ['Three reading questions', 'Tiga soal membaca', [['Main idea, referent, inference.', 'Ide pokok, rujukan, inferensi.'], ['Inference joins two stated facts; it never adds outside knowledge.', 'Inferensi menggabungkan dua fakta yang tertulis; tidak pernah menambah pengetahuan luar.']]],
    ['Learning agility', 'Learning agility', [['How you seek, process and apply experience.', 'Cara kamu mencari, mengolah, dan menerapkan pengalaman.'], ['Consistency across items is what is read; pretending shows.', 'Konsistensi antar soal yang dibaca; berpura-pura terlihat.']]]
  ]),
  sections: [
    sec('book', 'Structure: three families', 'Struktur: tiga keluarga', 'Business-English structure items recycle three families. <b>Agreement</b>: the verb agrees with the head noun (“the report, together with its appendices, <i>is</i> due”), with the nearer subject after “neither … nor”, and “every/each” is singular. <b>Tense and aspect</b>: “since” and “for” take the present perfect; “by the time” plus a future event takes the future perfect; third conditionals pair “had” with “would have”; after “recommend/suggest that” the verb is the base form. <b>Clause form</b>: non-defining relative clauses between commas take “which”; fronted negatives (“hardly”, “not only”) invert subject and auxiliary; “look forward to” takes the -ing form. Strip interrupting phrases, find the head noun, name the time marker, then choose.', 'Soal struktur bahasa Inggris bisnis mendaur ulang tiga keluarga. <b>Kesesuaian</b>: kata kerja sesuai dengan inti frasa (“the report, together with its appendices, <i>is</i> due”), dengan subjek terdekat setelah “neither … nor”, dan “every/each” tunggal. <b>Kala dan aspek</b>: “since” dan “for” memakai present perfect; “by the time” plus peristiwa mendatang memakai future perfect; kondisional ketiga memasangkan “had” dengan “would have”; setelah “recommend/suggest that” kata kerja berbentuk dasar. <b>Bentuk klausa</b>: klausa relatif non-pembatas di antara koma memakai “which”; negatif di depan (“hardly”, “not only”) membalik subjek dan kata bantu; “look forward to” memakai bentuk -ing. Buang frasa penyela, temukan inti frasa, sebutkan penanda waktu, lalu pilih.'),
    sec('search', 'Reading: three question types', 'Membaca: tiga jenis soal', 'Passages are short business texts (a trial of a new policy, a bank’s new process). <b>Main idea</b>: the option that covers both sides when the passage has two; details and single findings are distractors. <b>Referent</b>: a pronoun or “the change” points to the nearest grammatically possible subject that makes sense; replace it with each option and reread. <b>Inference</b>: join two stated facts (“Friday enquiries wait until Monday” plus “clients asked for a Friday contact” gives the reason for a Friday shift); any option that needs a fact the passage does not state is wrong, however reasonable. Read the question first, then the passage once, then locate.', 'Wacananya teks bisnis pendek (uji coba kebijakan baru, proses baru sebuah bank). <b>Ide pokok</b>: opsi yang mencakup kedua sisi ketika wacana punya dua; rincian dan temuan tunggal adalah pengecoh. <b>Rujukan</b>: kata ganti atau “the change” menunjuk subjek terdekat yang secara tata bahasa mungkin dan masuk akal; ganti dengan tiap opsi dan baca ulang. <b>Inferensi</b>: gabungkan dua fakta tertulis (“Friday enquiries wait until Monday” plus “clients asked for a Friday contact” memberi alasan sif Jumat); opsi apa pun yang membutuhkan fakta yang tidak disebut wacana salah, betapa pun masuk akalnya. Baca soalnya dulu, lalu wacananya sekali, lalu cari.'),
    sec('brain', 'What learning agility measures', 'Apa yang diukur learning agility', 'Learning-agility instruments ask about how you behave when the situation is new: whether you seek feedback, experiment, reflect on failure, read people and politics, keep composure under ambiguity, and apply lessons from one context to another. They are questionnaires with consistency checks, like the personality tests in Lesson 7.5, and the provider changes between cycles. There is no key, and the only preparation that helps is the honest one: decide what you actually do when things change (with one example each for seeking feedback, trying a new approach, and reflecting on a failure), and answer every item from that same picture of yourself. The Lab’s consistency mirror is the practice for this.', 'Instrumen learning agility menanyakan cara kamu berperilaku saat situasi baru: apakah kamu mencari umpan balik, bereksperimen, merenungkan kegagalan, membaca orang dan politik, menjaga ketenangan dalam ketidakjelasan, dan menerapkan pelajaran dari satu konteks ke konteks lain. Instrumen ini adalah kuesioner dengan pemeriksaan konsistensi, seperti tes kepribadian di Pelajaran 7.5, dan penyedianya berganti antar siklus. Tidak ada kunci, dan satu-satunya persiapan yang membantu adalah yang jujur: putuskan apa yang benar-benar kamu lakukan saat keadaan berubah (dengan satu contoh masing-masing untuk mencari umpan balik, mencoba pendekatan baru, dan merenungkan kegagalan), dan jawab setiap soal dari gambaran diri yang sama itu. Cermin konsistensi Lab adalah latihannya.'),
    sec('clock', 'Pacing the English set', 'Tempo set bahasa Inggris', 'Twenty items in twenty minutes: structure items take 30 seconds, reading items 60 to 90 with the passage read once. Read every structure item twice before answering; most misses are a time marker skipped on the first read. For reading, answer referent questions first (they are fastest), then main idea, then inference. Blank scores zero; answer everything.', 'Dua puluh soal dalam dua puluh menit: soal struktur memakan 30 detik, soal membaca 60 sampai 90 dengan wacana dibaca sekali. Baca tiap soal struktur dua kali sebelum menjawab; kebanyakan kesalahan adalah penanda waktu yang terlewat pada bacaan pertama. Untuk membaca, jawab soal rujukan dulu (paling cepat), lalu ide pokok, lalu inferensi. Kosong bernilai nol; jawab semuanya.')
  ],
  diagram: flow('Exhibit 1: Structure, in order', 'Peraga 1: Struktur, berurutan', 'Three questions before choosing the verb', 'Tiga pertanyaan sebelum memilih kata kerja', [
    ['search', 'Head noun?', 'Inti frasa?', 'Strip commas and “together with”; agree with the head.', 'Buang koma dan “together with”; sesuaikan dengan inti.'],
    ['clock', 'Time marker?', 'Penanda waktu?', 'since, for, by the time, if … would have.', 'since, for, by the time, if … would have.'],
    ['list', 'Clause form?', 'Bentuk klausa?', 'Commas → which; fronted negative → inversion; to + -ing after “look forward”.', 'Koma → which; negatif di depan → inversi; to + -ing setelah “look forward”.'],
    ['check', 'Choose', 'Pilih', 'Then read the sentence once more.', 'Lalu baca kalimatnya sekali lagi.']
  ]),
  compare: [cmp('Two readings of an agreement item', 'Dua pembacaan soal kesesuaian', '“The report, together with its three appendices, ___ due on Friday.”', '“The report, together with its three appendices, ___ due on Friday.”', 'Hears “appendices” and chooses “are”.', 'Mendengar “appendices” dan memilih “are”.', 'Strips the phrase between commas: “The report ___ due.” Chooses “is”.', 'Membuang frasa di antara koma: “The report ___ due.” Memilih “is”.', 'Agreement is with the head noun; interrupting phrases are the designed distractor.', 'Kesesuaian dengan inti frasa; frasa penyela adalah pengecoh rancangan.')],
  scenario: scen('brain', 'In focus: the consistent answer', 'Sorotan: jawaban yang konsisten', [['Two applicants answered the same agility questionnaire. One tried to “score high” and answered every item at the extreme; the instrument’s consistency checks flagged the profile. The other answered from three real examples he had written down the night before; his profile was moderate and consistent, and he passed to the enterprise stage.', 'Dua pelamar menjawab kuesioner agility yang sama. Satu mencoba “mendapat skor tinggi” dan menjawab setiap soal di titik ekstrem; pemeriksaan konsistensi instrumen menandai profilnya. Yang lain menjawab dari tiga contoh nyata yang ia tulis malam sebelumnya; profilnya moderat dan konsisten, dan ia lolos ke tahap BUMN.']]),
  steps: [
    step('Drill 1 · Structure, three questions each', 'Latihan 1 · Struktur, tiga pertanyaan tiap soal', 'Fourteen structure items in the Lab. Write “head / time / clause” next to each before answering.', 'Empat belas soal struktur di Lab. Tulis “inti / waktu / klausa” di samping tiap soal sebelum menjawab.', 'Misses tagged “nearest noun agreement” and “tense marker ignored” are the two habits; each has one fix.', 'Kesalahan bertanda “kesesuaian kata terdekat” dan “penanda kala diabaikan” adalah dua kebiasaan; masing-masing punya satu perbaikan.'),
    step('Drill 2 · Two passages, three types', 'Latihan 2 · Dua wacana, tiga jenis', 'Twelve reading items on the Lab’s two original passages. Answer referents first, then main idea, then inference.', 'Dua belas soal membaca pada dua wacana asli Lab. Jawab rujukan dulu, lalu ide pokok, lalu inferensi.', 'Every inference you missed needed a fact outside the passage; find the sentence that would have been required.', 'Setiap inferensi yang kamu lewatkan membutuhkan fakta di luar wacana; temukan kalimat yang seharusnya diperlukan.'),
    step('Drill 3 · Three true examples', 'Latihan 3 · Tiga contoh nyata', 'Write one real example each of seeking feedback, trying a new approach, and reflecting on a failure. Then run the Lab’s consistency mirror.', 'Tulis satu contoh nyata masing-masing untuk mencari umpan balik, mencoba pendekatan baru, dan merenungkan kegagalan. Lalu jalankan cermin konsistensi Lab.', 'The examples are the Dossier item and the interview material for The Rope; the mirror shows whether your questionnaire answers match them.', 'Contoh-contoh itu adalah butir Dossier dan bahan wawancara untuk The Rope; cermin menunjukkan apakah jawaban kuesionermu cocok dengannya.')
  ],
  mistakes: mist([['Agreeing with the nearest noun', 'Menyesuaikan dengan kata benda terdekat', 'Strip the phrase; agree with the head.', 'Buang frasanya; sesuaikan dengan inti.'], ['Inferring from the world, not the passage', 'Menyimpulkan dari dunia, bukan wacana', 'Two stated facts, joined; nothing added.', 'Dua fakta tertulis, digabung; tidak ada yang ditambah.'], ['Answering agility items at the extreme', 'Menjawab soal agility di titik ekstrem', 'Answer from real examples; consistency is what is read.', 'Jawab dari contoh nyata; konsistensi yang dibaca.'], ['Leaving English items blank', 'Membiarkan soal bahasa Inggris kosong', 'Blank is zero; answer everything.', 'Kosong adalah nol; jawab semuanya.']]),
  glossary: gl([['Head noun', 'Inti frasa', 'The noun the verb agrees with, before any interrupting phrase.', 'Kata benda yang disesuaikan kata kerja, sebelum frasa penyela.'], ['Present perfect', 'Present perfect', 'has/have + past participle; with since and for.', 'has/have + past participle; dengan since dan for.'], ['Non-defining clause', 'Klausa non-pembatas', 'Extra information between commas; takes “which”.', 'Informasi tambahan di antara koma; memakai “which”.'], ['Inversion', 'Inversi', 'Auxiliary before subject after a fronted negative.', 'Kata bantu sebelum subjek setelah negatif di depan.'], ['Referent', 'Rujukan', 'What a pronoun or noun phrase points back to.', 'Hal yang ditunjuk kembali oleh kata ganti atau frasa.'], ['Learning agility', 'Learning agility', 'Disposition to learn from new experience; questionnaire-based, provider-specific.', 'Disposisi belajar dari pengalaman baru; berbasis kuesioner, khas penyedia.']]),
  checks: [
    chk('“Neither the supervisor nor the technicians ___ aware.” The verb is …', '“Neither the supervisor nor the technicians ___ aware.” Kata kerjanya …', [['was', 'was'], ['were', 'were'], ['is', 'is'], ['has been', 'has been']], 1, 'With neither/nor the verb agrees with the nearer subject, “technicians”.', 'Dengan neither/nor kata kerja sesuai subjek terdekat, “technicians”.'),
    chk('An inference answer is wrong if …', 'Jawaban inferensi salah jika …', [['it uses two sentences from the passage', 'memakai dua kalimat dari wacana'], ['it needs a fact the passage never states', 'membutuhkan fakta yang tidak pernah disebut wacana'], ['it is short', 'pendek'], ['it restates the title', 'mengulang judul']], 1, 'Inference joins stated facts only.', 'Inferensi hanya menggabungkan fakta yang tertulis.'),
    chk('The best preparation for a learning-agility questionnaire is …', 'Persiapan terbaik untuk kuesioner learning agility adalah …', [['answering every item at the top of the scale', 'menjawab setiap soal di puncak skala'], ['three true examples and consistent answers from them', 'tiga contoh nyata dan jawaban konsisten darinya'], ['finding last cycle’s items', 'mencari soal siklus lalu'], ['skipping it', 'melewatkannya']], 1, 'Consistency checks read the profile; pretending shows.', 'Pemeriksaan konsistensi membaca profil; berpura-pura terlihat.')
  ],
  tool: tool('timed:english20', 'The 20-item English set', 'Set bahasa Inggris 20 soal', 'Fourteen structure items and twelve reading items in the bank; the timed set draws twenty in twenty minutes with structured feedback after. Then the consistency mirror for the agility round.', 'Empat belas soal struktur dan dua belas soal membaca di bank; set berbatas waktu mengambil dua puluh dalam dua puluh menit dengan umpan balik terstruktur sesudahnya. Lalu cermin konsistensi untuk putaran agility.'),
  takeaways: take([['Head noun, time marker, clause form: three questions, then the verb.', 'Inti frasa, penanda waktu, bentuk klausa: tiga pertanyaan, lalu kata kerja.'], ['Inference joins stated facts; it never adds.', 'Inferensi menggabungkan fakta tertulis; tidak pernah menambah.'], ['Agility: real examples, consistent answers, no pretending.', 'Agility: contoh nyata, jawaban konsisten, tanpa berpura-pura.']]),
  resources: res('Verification', 'Verifikasi', 'Provider and format.', 'Penyedia dan format.', [['Per cycle', 'Per siklus', 'The English provider, band thresholds and the agility instrument change.', 'Penyedia bahasa Inggris, ambang pita, dan instrumen agility berubah.', [[VERIFY.en, VERIFY.id], [NOTICE.en, NOTICE.id]]]])
});

const L1210 = lesson({
  n: '12.10', kind: 'interactive', dur: dur(80, b('the mock', 'simulasi')),
  title: b('BUMN-T1 Mock: TKD and AKHLAK Together', 'Simulasi BUMN-T1: TKD dan AKHLAK Bersama'),
  overview: b('The Track B checkpoint reproduces the shape of the first online round in Metanoia’s practice format: a 60-item, 45-minute TKD followed, after a short break, by a 30-scenario, 25-minute AKHLAK set with ranked scoring. The report covers both: family grid and pacing for the TKD, value profile, second-best share and trap tags for AKHLAK, and a readiness checklist that is never a prediction.', 'Titik periksa Jalur B mereproduksi bentuk putaran daring pertama dalam format latihan Metanoia: TKD 60 soal, 45 menit, diikuti, setelah jeda singkat, set AKHLAK 30 skenario, 25 menit dengan skor berjenjang. Laporannya mencakup keduanya: kisi keluarga dan tempo untuk TKD, profil nilai, porsi terbaik kedua, dan tanda jebakan untuk AKHLAK, dan daftar periksa kesiapan yang tidak pernah menjadi ramalan.'),
  objectives: [b('Sit two tests back to back and manage the transition.', 'Mengerjakan dua tes berurutan dan mengelola peralihannya.'), b('Read a combined report and locate the larger gain.', 'Membaca laporan gabungan dan menemukan perolehan yang lebih besar.'), b('Complete the readiness checklist honestly.', 'Melengkapi daftar periksa kesiapan dengan jujur.'), b('Plan the final week before the real first round.', 'Merencanakan minggu terakhir sebelum putaran pertama sungguhan.')],
  readFirst: rf('Two tests, one sitting', 'Dua tes, satu kali duduk', 'The round-1 shape, reproduced honestly.', 'Bentuk putaran 1, direproduksi dengan jujur.', [
    ['TKD then AKHLAK', 'TKD lalu AKHLAK', [['60 items in 45 minutes, a short break, 30 scenarios in 25 minutes.', '60 soal dalam 45 menit, jeda singkat, 30 skenario dalam 25 menit.'], ['The transition is a skill: breathe, reread the ladder, start.', 'Peralihan adalah keterampilan: bernapas, baca ulang tangga, mulai.']]],
    ['Two reports', 'Dua laporan', [['TKD: family grid, pacing. AKHLAK: value profile, second-best share.', 'TKD: kisi keluarga, tempo. AKHLAK: profil nilai, porsi terbaik kedua.'], ['The larger gain is usually in AKHLAK 4s, not TKD knowledge.', 'Perolehan lebih besar biasanya ada di AKHLAK 4, bukan pengetahuan TKD.']]],
    ['A checklist, not a prediction', 'Daftar periksa, bukan ramalan', [['Readiness is what you can verify: facts written, device tested, pacing rehearsed.', 'Kesiapan adalah yang bisa diverifikasi: fakta tertulis, perangkat teruji, tempo terlatih.'], ['No Lab number predicts a pass.', 'Tidak ada angka Lab yang meramalkan kelulusan.']]]
  ]),
  sections: [
    sec('checkSq', 'The sitting', 'Duduknya', 'The round-1 shape has typically been a TKD followed by the AKHLAK test in one session, sometimes with a national-insight component; verify the current composition. The Lab’s BUMN-T1 mock runs the TKD (60 items, 45 minutes), a three-minute break, then the AKHLAK set (30 scenarios, 25 minutes). Sit it on the device and at the hour of your real sitting, with the six facts from 12.7 on your card. The break is for water and the ladder, not for checking the TKD.', 'Bentuk putaran 1 biasanya TKD diikuti tes AKHLAK dalam satu sesi, kadang dengan komponen wawasan kebangsaan; verifikasi komposisi yang berlaku. Simulasi BUMN-T1 Lab menjalankan TKD (60 soal, 45 menit), jeda tiga menit, lalu set AKHLAK (30 skenario, 25 menit). Kerjakan pada perangkat dan jam duduk sungguhanmu, dengan enam fakta dari 12.7 di kartumu. Jeda untuk minum air dan tangga, bukan untuk memeriksa TKD.'),
    sec('refresh', 'The transition', 'Peralihan', 'The TKD leaves you in computation mode; AKHLAK needs judgement mode. Candidates who start the scenarios still “solving” pick the clever option instead of the right one. Use the break: three breaths, reread the ladder (fixes, helps, defers, avoids, harms), say the six values once, and start by naming the value under pressure on scenario 1 before reading its options. The first three scenarios set the mode for the rest.', 'TKD meninggalkanmu dalam mode perhitungan; AKHLAK membutuhkan mode pertimbangan. Kandidat yang memulai skenario sambil masih “memecahkan” memilih opsi yang cerdik alih-alih yang benar. Pakai jedanya: tiga tarikan napas, baca ulang tangga (membereskan, membantu, menyerahkan, menghindar, merugikan), ucapkan enam nilai sekali, dan mulailah dengan menamai nilai yang tertekan pada skenario 1 sebelum membaca opsinya. Tiga skenario pertama menetapkan mode untuk sisanya.'),
    sec('chart', 'Reading the combined report', 'Membaca laporan gabungan', 'Two reports, read in the same order as always: grid before numbers. For the TKD: the family grid, completion, median time per family. For AKHLAK: the value profile (your mean score per value out of 5), the second-best share, trap tags (heroic, loyal-to-person, second-best), and any blanks. Then compare the two for the larger available gain: a TKD at 70% with an AKHLAK second-best share of 60% gains more from one ladder session than from a week of numerical drills, because 4s become 5s in one sitting and knowledge does not.', 'Dua laporan, dibaca dalam urutan yang selalu sama: kisi sebelum angka. Untuk TKD: kisi keluarga, penyelesaian, waktu median per keluarga. Untuk AKHLAK: profil nilai (skor rata-ratamu per nilai dari 5), porsi terbaik kedua, tanda jebakan (heroik, setia-pada-orang, terbaik kedua), dan kosong apa pun. Lalu bandingkan keduanya untuk perolehan terbesar yang tersedia: TKD 70% dengan porsi terbaik kedua AKHLAK 60% mendapat lebih banyak dari satu sesi tangga daripada dari seminggu latihan numerik, karena 4 menjadi 5 dalam satu kali duduk dan pengetahuan tidak.'),
    sec('list', 'The readiness checklist', 'Daftar periksa kesiapan', 'Readiness is a list of things you can verify, never a number: the six facts written and checked against the current announcement; the device, connection, camera and browser tested in the sitting window; the TKD pacing rehearsed with checkpoints at least twice; the AKHLAK ladder applied with a second-best share under 30% on the last two sets; the mirror run with no disagreements; the English set sat once; sleep, food and the quiet room arranged. The Lab shows the checklist with your own ticks; it does not and cannot say whether you will pass, because no practice bank predicts an institution’s cut.', 'Kesiapan adalah daftar hal yang bisa kamu verifikasi, bukan angka: enam fakta ditulis dan diperiksa terhadap pengumuman yang berlaku; perangkat, koneksi, kamera, dan peramban diuji dalam jendela pengerjaan; tempo TKD dilatih dengan titik periksa setidaknya dua kali; tangga AKHLAK diterapkan dengan porsi terbaik kedua di bawah 30% pada dua set terakhir; cermin dijalankan tanpa ketidaksepakatan; set bahasa Inggris dikerjakan sekali; tidur, makanan, dan ruangan tenang diatur. Lab menampilkan daftar periksa dengan centangmu sendiri; Lab tidak dan tidak bisa mengatakan apakah kamu akan lulus, karena tidak ada bank latihan yang meramalkan ambang sebuah lembaga.')
  ],
  diagram: flow('Exhibit 1: BUMN-T1', 'Peraga 1: BUMN-T1', 'The mock’s shape and its two reports', 'Bentuk simulasi dan dua laporannya', [
    ['layers', 'TKD · 60 in 45', 'TKD · 60 dalam 45', 'Four families, checkpoints, flags.', 'Empat keluarga, titik periksa, tanda.'],
    ['hourglass', 'Break · 3 min', 'Jeda · 3 mnt', 'Water, ladder, six values.', 'Air, tangga, enam nilai.'],
    ['heart', 'AKHLAK · 30 in 25', 'AKHLAK · 30 dalam 25', 'Ranked scoring; name the value first.', 'Skor berjenjang; sebutkan nilainya dulu.'],
    ['chart', 'Reports', 'Laporan', 'Grid and pacing; value profile and second-best share.', 'Kisi dan tempo; profil nilai dan porsi terbaik kedua.']
  ]),
  compare: [cmp('Two final weeks', 'Dua minggu terakhir', 'Seven days to the real round 1; mock TKD 72%, AKHLAK second-best share 58%.', 'Tujuh hari menuju putaran 1 sungguhan; TKD simulasi 72%, porsi terbaik kedua AKHLAK 58%.', 'Spends the week on numerical drills because “numbers are where marks are”. Round 1: TKD slightly up, AKHLAK unchanged.', 'Menghabiskan minggu itu untuk latihan numerik karena “angka adalah tempat nilai”. Putaran 1: TKD sedikit naik, AKHLAK tak berubah.', 'Spends three sessions on the AKHLAK ladder (second-best share to 25%), two on TKD timed sets, one on the English set, one on the device and the facts. Round 1: AKHLAK up by the equivalent of ten scenarios.', 'Menghabiskan tiga sesi untuk tangga AKHLAK (porsi terbaik kedua ke 25%), dua untuk set TKD berbatas waktu, satu untuk set bahasa Inggris, satu untuk perangkat dan fakta. Putaran 1: AKHLAK naik setara sepuluh skenario.', 'The combined report locates the larger gain; the final week goes there.', 'Laporan gabungan menemukan perolehan yang lebih besar; minggu terakhir pergi ke sana.')],
  scenario: scen('checkSq', 'In focus: the checklist with two blanks', 'Sorotan: daftar periksa dengan dua kosong', [['A candidate’s checklist on the night before had every tick except two: the device had not been tested in the sitting window and the six facts had been copied from last year’s announcement. The next morning the portal required a browser extension she had never installed, and the TKD had five fewer items than her pacing plan assumed. She passed, narrowly, and wrote the two blanks into the Dossier as the lesson.', 'Daftar periksa seorang kandidat pada malam sebelumnya memiliki setiap centang kecuali dua: perangkat belum diuji dalam jendela pengerjaan dan enam fakta disalin dari pengumuman tahun lalu. Keesokan paginya portal mewajibkan ekstensi peramban yang belum pernah ia pasang, dan TKD punya lima soal lebih sedikit daripada yang diandaikan rencana temponya. Ia lulus, tipis, dan menulis dua kosong itu ke Dossier sebagai pelajarannya.']]),
  steps: [
    step('Step 1 · Sit the BUMN-T1 mock', 'Langkah 1 · Kerjakan simulasi BUMN-T1', 'TKD, break, AKHLAK, on the real device at the real hour with the card on the desk.', 'TKD, jeda, AKHLAK, pada perangkat sungguhan pada jam sungguhan dengan kartu di meja.', 'Use the break for the ladder, not for the TKD.', 'Pakai jeda untuk tangga, bukan untuk TKD.'),
    step('Step 2 · Locate the larger gain', 'Langkah 2 · Temukan perolehan yang lebih besar', 'Read both reports, grid first. Decide in one line where the final week goes and why.', 'Baca kedua laporan, kisi dulu. Putuskan dalam satu baris ke mana minggu terakhir pergi dan mengapa.', 'If the second-best share is above 30%, the line is AKHLAK; if completion is under 85%, TKD pacing; otherwise the reddest sub-type.', 'Jika porsi terbaik kedua di atas 30%, barisnya AKHLAK; jika penyelesaian di bawah 85%, tempo TKD; selain itu sub-tipe paling merah.'),
    step('Step 3 · Tick the checklist honestly', 'Langkah 3 · Centang daftar periksa dengan jujur', 'Every item on the readiness checklist is either verified or not. Write the blanks into the plan for the final week. Record the mock and the checklist as Dossier item 3.', 'Setiap butir daftar periksa kesiapan terverifikasi atau tidak. Tulis yang kosong ke rencana minggu terakhir. Catat simulasi dan daftar periksa sebagai butir Dossier 3.', 'A blank tick is a task, not a verdict.', 'Centang kosong adalah tugas, bukan vonis.')
  ],
  mistakes: mist([['Checking TKD answers in the break', 'Memeriksa jawaban TKD saat jeda', 'The break is for switching modes.', 'Jeda untuk berganti mode.'], ['Spending the final week on knowledge', 'Menghabiskan minggu terakhir untuk pengetahuan', 'Find the larger gain; it is usually the 4s.', 'Temukan perolehan yang lebih besar; biasanya nilai 4.'], ['Copying last year’s facts', 'Menyalin fakta tahun lalu', 'Verify against the current announcement.', 'Verifikasi terhadap pengumuman yang berlaku.'], ['Reading readiness as a prediction', 'Membaca kesiapan sebagai ramalan', 'It is a list of verified tasks; nothing predicts a pass.', 'Itu daftar tugas terverifikasi; tidak ada yang meramalkan kelulusan.']]),
  glossary: gl([['BUMN-T1', 'BUMN-T1', 'The Lab’s round-1 mock: TKD then AKHLAK, in Metanoia’s practice format.', 'Simulasi putaran 1 Lab: TKD lalu AKHLAK, dalam format latihan Metanoia.'], ['Value profile', 'Profil nilai', 'Mean ranked score per AKHLAK value.', 'Skor berjenjang rata-rata per nilai AKHLAK.'], ['Transition', 'Peralihan', 'Switching from computation to judgement between the two tests.', 'Berganti dari perhitungan ke pertimbangan di antara dua tes.'], ['Readiness checklist', 'Daftar periksa kesiapan', 'Verifiable tasks before the test; never a prediction.', 'Tugas terverifikasi sebelum tes; tidak pernah ramalan.'], ['Sitting window', 'Jendela pengerjaan', 'The dates and hours in which the real test can be taken.', 'Tanggal dan jam saat tes sungguhan bisa dikerjakan.'], ['Larger gain', 'Perolehan lebih besar', 'The report area where one week of work moves the most points.', 'Area laporan tempat satu minggu kerja menggerakkan poin terbanyak.']]),
  checks: [
    chk('The break between the TKD and the AKHLAK set is for …', 'Jeda antara TKD dan set AKHLAK adalah untuk …', [['checking TKD answers', 'memeriksa jawaban TKD'], ['switching modes: water, the ladder, the six values', 'berganti mode: air, tangga, enam nilai'], ['reading the news', 'membaca berita'], ['nothing; skip it', 'tidak ada; lewati']], 1, 'Judgement mode must replace computation mode before scenario 1.', 'Mode pertimbangan harus menggantikan mode perhitungan sebelum skenario 1.'),
    chk('With TKD 72% and an AKHLAK second-best share of 58%, the final week goes to …', 'Dengan TKD 72% dan porsi terbaik kedua AKHLAK 58%, minggu terakhir pergi ke …', [['numerical drills', 'latihan numerik'], ['the AKHLAK ladder, then TKD timed sets', 'tangga AKHLAK, lalu set TKD berbatas waktu'], ['the Kraepelin simulator', 'simulator Kraepelin'], ['rest only', 'istirahat saja']], 1, '4s become 5s in one sitting; that is the larger gain.', '4 menjadi 5 dalam satu kali duduk; itulah perolehan yang lebih besar.'),
    chk('The readiness checklist tells you …', 'Daftar periksa kesiapan memberi tahu …', [['your probability of passing', 'peluang lulusmu'], ['which verifiable tasks are done and which are not', 'tugas terverifikasi mana yang selesai dan mana yang belum'], ['your rank among users', 'peringkatmu di antara pengguna'], ['the cut-off score', 'skor ambang']], 1, 'No practice bank predicts an institution’s cut; readiness is tasks.', 'Tidak ada bank latihan yang meramalkan ambang lembaga; kesiapan adalah tugas.')
  ],
  tool: tool('mock:bumn-t1', 'The BUMN-T1 mock', 'Simulasi BUMN-T1', 'TKD (60 items, 45 minutes), a three-minute break, AKHLAK (30 scenarios, 25 minutes, ranked); two reports and the readiness checklist. A Metanoia practice form in a round-1-like shape; not an imitation of any institution’s interface or brand.', 'TKD (60 soal, 45 menit), jeda tiga menit, AKHLAK (30 skenario, 25 menit, berjenjang); dua laporan dan daftar periksa kesiapan. Formulir latihan Metanoia dalam bentuk mirip putaran 1; bukan tiruan antarmuka atau merek lembaga mana pun.', 'Start the mock →', 'Mulai simulasi →'),
  takeaways: take([['Two tests, one sitting; the break switches modes.', 'Dua tes, satu kali duduk; jeda mengganti mode.'], ['Grid first in both reports; the larger gain is usually the 4s.', 'Kisi dulu di kedua laporan; perolehan lebih besar biasanya nilai 4.'], ['Readiness is verified tasks, never a prediction.', 'Kesiapan adalah tugas terverifikasi, tidak pernah ramalan.']]),
  resources: res('Before round 1', 'Sebelum putaran 1', 'The facts and the device.', 'Fakta dan perangkat.', [['Verify', 'Verifikasi', 'Current announcement and portal rules.', 'Pengumuman dan aturan portal yang berlaku.', [[VERIFY.en, VERIFY.id], [NOTICE.en, NOTICE.id]]]])
});

module.exports = { lessons: [L127, L128, L129, L1210] };
